record.field:
picking = env['stock.picking'].browse(record.res_id).exists()

if picking:
    feedback = (
        'Picking %s chưa đủ hàng để reservation. '
        'Vui lòng bổ sung tồn kho tại location nguồn và kiểm tra khả dụng lại.'
    ) % picking.name

    picking.message_post_with_source(
        'mail.message_activity_done',
        render_values={
            'activity': record,
            'feedback': feedback,
            'display_assignee': record.user_id != env.user,
        },
        mail_activity_type_id=record.activity_type_id.id,
        subtype_xmlid='mail.mt_activities',
    )

picking = env['stock.picking'].browse(record.res_id).exists()

if picking and picking.state != 'done':
    picking.action_assign()

    if picking.state != 'assigned':
        env.ref(
            'fmcg_business_automation.action_feedback_picking_availability'
        ).with_context(
            active_model='mail.activity',
            active_id=record.id,
            active_ids=[record.id],
        ).run()

        activity_type = env.ref(
            'fmcg_business_automation.mail_activity_type_check_picking_availability'
        )

        record.write({
            'active': True,
            'feedback': False,
        })
